/**
 * BundleMcp
 *
 * An MCP server to provision for the package.
 */
export type BundleMcp = {
    /**
     * Bindings
     *
     * Maps an env var / header name the server needs to a ${setup.x} reference, e.g. {'GITHUB_TOKEN': '${setup.github_token}'}.
     */
    bindings?: {
        [key: string]: string;
    };
    /**
     * Context Secret
     *
     * URL MCPs only. A ${setup.x} reference to a secret setup field whose value becomes the instance's context_secret: the key AgentArea signs each tool call's context with. Write-only, like a header secret.
     */
    context_secret?: string | null;
    /**
     * Json Spec
     *
     * Native MCP runtime spec. Must include 'type' (command|docker|url).
     */
    json_spec: {
        [key: string]: unknown;
    };
    /**
     * Key
     *
     * In-package reference key (agents point at this).
     */
    key: string;
    /**
     * Name
     *
     * Instance display name created in the workspace.
     */
    name: string;
};

